//! Actions-only manual nonUID intent/migration/no-grant SQL boundaries.
//! A scalar UID/local observation/hash/status never supplies private network reply.
use super::*;
fn uri()->&'static[u8]{b"[phone:+12345@fixture.invalid]"}
fn digest(value:&[u8])->Vec<u8>{let mut h=ring::digest::Context::new(&ring::digest::SHA256);h.update(b"original-im-read-status-recipient-v1\0");h.update(&(value.len()as u64).to_be_bytes());h.update(value);h.finish().as_ref().to_vec()}
fn alias(f:&Fixture,t:&Arc<ReadStatusTargets>,nonce:&str,uri:&[u8])->Arc<ReadStatusAction>{let v=t.list().pop().unwrap();ReadStatusAction::original_with_recipient(f.temp.database.clone(),f.run.clone(),f.gate.clone(),f.owner.clone(),f.scope.clone(),t.get(v.id,&v.target_index).unwrap(),nonce,Instant::now()+Duration::from_secs(30),uri).unwrap()}
#[test]fn manual_recipient_intent_accepts_only_typed_nonuid_for_current_p2p_span(){let mut f=Fixture::new(true);let(t,_)=setup(&mut f,false);let id=t.list()[0].id;for u in [b"1_2".as_slice(),b"[uid:1_2]",b"12345",b"scheme://fixture.invalid"]{assert!(ReadStatusAction::original_with_recipient(f.temp.database.clone(),f.run.clone(),f.gate.clone(),f.owner.clone(),f.scope.clone(),t.get(id,"7").unwrap(),&"a".repeat(32),Instant::now()+Duration::from_secs(1),u).is_err());}let a=alias(&f,&t,&"a".repeat(32),uri());assert!(a.recipient_action().is_some());assert!(a.recipient_preflight().unwrap().is_none());let mut f=Fixture::new(true);let(t,_)=setup(&mut f,true);let id=t.list()[0].id;assert!(ReadStatusAction::original_with_recipient(f.temp.database.clone(),f.run.clone(),f.gate.clone(),f.owner.clone(),f.scope.clone(),t.get(id,"7").unwrap(),&"a".repeat(32),Instant::now()+Duration::from_secs(1),uri()).is_err());}
#[test]fn manual_recipient_current_span_and_group_report_cannot_mint_write_without_private_uid_reply(){let mut f=Fixture::new(true);let(t,_)=setup(&mut f,false);let a=alias(&f,&t,&"a".repeat(32),uri());assert_eq!(n::im_inbox::begin_read_status(f.temp.database.clone(),a.clone(),&policy()).err(),Some("app_account_im_read_status_recipient_unconfirmed"));let rows:i64=f.temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_read_status_actions",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(rows,0);let r=f.backend.prepare_im_read(Arc::new(ImQuery::refresh(&[],-1).unwrap()),f.gate.clone(),a.deadline()).unwrap();assert_eq!(r.call_id,4);assert!(f.scope.is_open());}
#[test]fn manual_recipient_unknown_original_default_action_blocks_alias_nonce_before_auxiliary_query(){let mut f=Fixture::new(true);let(t,a)=setup(&mut f,false);let _p=prepared(&f,&a);let a=alias(&f,&t,&"b".repeat(32),uri());assert_eq!(a.recipient_preflight().err(),Some("app_account_im_receipt_uncertain"));assert_eq!(manual_state(&f),(0,None));assert!(f.scope.is_open());}
#[test]fn manual_recipient_unknown_automatic_receipt_is_not_cleared_by_lookup_intent(){let mut f=Fixture::new(true);let(t,a)=setup(&mut f,false);let _p=admit(&f,a.span());let a=alias(&f,&t,&"b".repeat(32),uri());assert_eq!(a.recipient_preflight().err(),Some("app_account_im_receipt_uncertain"));assert_eq!(state(&f),(0,None,7));}
#[test]fn manual_recipient_same_nonce_cannot_promote_legacy_null_hash_into_new_alias_intent(){let mut f=Fixture::new(true);let(t,a)=setup(&mut f,false);let p=prepared(&f,&a);p.cancel();let alias=alias(&f,&t,&"a".repeat(32),uri());assert_eq!(alias.recipient_preflight().err(),Some("app_account_im_read_status_nonce_conflict"));assert_eq!(manual_state(&f),(3,None));}
#[test]fn manual_recipient_hash_is_only_replay_correlation_and_changed_uri_conflicts_without_io(){let mut f=Fixture::new(true);let(t,a)=setup(&mut f,false);let p=prepared(&f,&a);p.cancel();f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_im_read_status_actions SET recipient_hash=?1",[digest(uri())]).map_err(|_|"fixture")).unwrap();let a=alias(&f,&t,&"a".repeat(32),uri());assert_eq!(a.recipient_preflight().unwrap().unwrap().state,"not_sent");let a=alias(&f,&t,&"a".repeat(32),b"[phone:+67890@fixture.invalid]");assert_eq!(a.recipient_preflight().err(),Some("app_account_im_read_status_nonce_conflict"));assert_eq!(manual_state(&f),(3,None));}
#[test]fn manual_recipient_changed_digest_before_arm_cannot_authorize_or_consume_write_id(){let mut f=Fixture::new(true);let(_,a)=setup(&mut f,false);let p=prepared(&f,&a);f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_im_read_status_actions SET recipient_hash=?1",[digest(uri())]).map_err(|_|"fixture")).unwrap();assert!(f.backend.prepare_received_write(p.clone(),a.deadline()).is_err());p.cancel();assert_eq!(manual_state(&f),(0,None));assert_eq!(state(&f),(0,None,7));assert!(f.scope.is_open());}
#[test]fn manual_recipient_changed_digest_after_submission_keeps_original_unknown_not_positive_result(){let mut f=Fixture::new(true);let(_,a)=setup(&mut f,false);let p=prepared(&f,&a);let packet=write(&mut f,&p);assert!(p.begin_write(packet.call_id));assert!(p.submitted());let reply=result(&mut f,packet.call_id,true,0);f.temp.database.with_conn(|c|c.execute("UPDATE app_voice_im_read_status_actions SET recipient_hash=?1",[digest(uri())]).map_err(|_|"fixture")).unwrap();assert!(p.resolve_original(&reply).is_err());assert_eq!(manual_state(&f),(0,Some(packet.call_id)));assert_eq!(state(&f),(0,Some(packet.call_id),7));p.cancel();assert!(!f.scope.is_open());}
#[test]fn manual_recipient_write_admission_stage_is_not_a_reply_grant_and_never_returns_to_prewrite(){let mut f=Fixture::new(true);let(_,a)=setup(&mut f,false);assert!(!a.write_admission_observed());let p=prepared(&f,&a);assert!(a.write_admission_observed());assert_eq!(manual_state(&f),(0,None));p.cancel();assert!(a.write_admission_observed());assert_eq!(manual_state(&f),(3,None));assert!(f.scope.is_open());}
#[test]fn manual_recipient_private_debug_does_not_export_uri_uid_nonce_or_routing(){let mut f=Fixture::new(true);let(t,_)=setup(&mut f,false);let a=alias(&f,&t,&"a".repeat(32),uri());let text=format!("{a:?}");for private in ["12345","1_2","nonce","token","fixture"]{assert!(!text.contains(private));}f.gate.retire();assert!(!a.live());assert!(a.recipient_preflight().is_err());assert!(f.scope.is_open());}
#[test]fn manual_recipient_inflight_same_nonce_and_changed_metadata_never_claim_a_second_query(){let mut f=Fixture::new(true);let(t,_)=setup(&mut f,false);let a=alias(&f,&t,&"a".repeat(32),uri());let _guard=a.claim_recipient_resolution().unwrap();let same=alias(&f,&t,&"a".repeat(32),uri());assert_eq!(same.claim_recipient_resolution().err(),Some("app_account_im_read_status_resolution_inflight"));let changed=alias(&f,&t,&"a".repeat(32),b"[phone:+67890@fixture.invalid]");assert_eq!(changed.claim_recipient_resolution().err(),Some("app_account_im_read_status_nonce_conflict"));assert!(a.recipient_preflight().unwrap().is_none());}
#[test]fn manual_recipient_pending_alias_and_default_intent_share_original_nonce_exclusion(){let mut f=Fixture::new(true);let(t,a)=setup(&mut f,false);let intent=alias(&f,&t,&"a".repeat(32),uri());let guard=intent.claim_recipient_resolution().unwrap();assert_eq!(a.claim_recipient_resolution().err(),Some("app_account_im_read_status_nonce_conflict"));drop(guard);assert_eq!(a.claim_recipient_resolution().err(),Some("app_account_im_read_status_nonce_conflict"));let mut f=Fixture::new(true);let(t,a)=setup(&mut f,false);let _guard=a.claim_recipient_resolution().unwrap();let alias=alias(&f,&t,&"a".repeat(32),uri());assert_eq!(alias.claim_recipient_resolution().err(),Some("app_account_im_read_status_nonce_conflict"));assert!(f.scope.is_open());}
#[test]fn manual_recipient_completed_read_attempt_is_not_requeried_for_same_nonce_or_replaced_uri(){let mut f=Fixture::new(true);let(t,_)=setup(&mut f,false);let a=alias(&f,&t,&"a".repeat(32),uri());drop(a.claim_recipient_resolution().unwrap());let same=alias(&f,&t,&"a".repeat(32),uri());assert_eq!(same.claim_recipient_resolution().err(),Some("app_account_im_read_status_resolution_finished"));let fresh=alias(&f,&t,&"b".repeat(32),uri());assert!(fresh.claim_recipient_resolution().is_ok());assert!(f.scope.is_open());}
#[test]fn manual_recipient_resolution_ledger_remains_bounded_and_retirement_never_resets_sdk_scope(){let mut f=Fixture::new(true);let(t,_)=setup(&mut f,false);for i in 0..128{let a=alias(&f,&t,&format!("{i:032x}"),uri());drop(a.claim_recipient_resolution().unwrap());}let a=alias(&f,&t,&format!("{:032x}",128),uri());assert_eq!(a.claim_recipient_resolution().err(),Some("app_account_im_read_status_recipient_capacity"));t.clear();assert!(a.claim_recipient_resolution().is_err());assert!(f.scope.is_open());}
#[test]fn manual_recipient_stale_prelookup_target_is_known_no_write_not_an_unknown_marker(){let mut f=Fixture::new(true);let(t,_)=setup(&mut f,false);let a=alias(&f,&t,&"a".repeat(32),uri());let later=span(&mut f,0,8,2);t.observe(&later).unwrap();assert_eq!(a.recipient_preflight().err(),Some("app_account_im_read_status_recipient_target_stale"));let rows:i64=f.temp.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_im_read_status_actions",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(rows,0);assert!(f.scope.is_open());}
#[test]fn manual_recipient_schema_migration_adds_nullable_hash_preserving_old_position_action(){let conn=rusqlite::Connection::open_in_memory().unwrap();conn.execute_batch("CREATE TABLE app_voice_im_read_status_actions(id INTEGER PRIMARY KEY AUTOINCREMENT,line_id TEXT NOT NULL,revision INTEGER NOT NULL,target_id INTEGER NOT NULL,identity_key BLOB NOT NULL,box_id BLOB NOT NULL,target_index INTEGER NOT NULL,span_hash BLOB NOT NULL,user_nonce TEXT NOT NULL,run_nonce TEXT NOT NULL,scope_epoch TEXT NOT NULL,state INTEGER NOT NULL,request_id INTEGER,result_code INTEGER,updated_at TEXT NOT NULL,UNIQUE(line_id,user_nonce));INSERT INTO app_voice_im_read_status_actions VALUES(1,'line',1,2,zeroblob(32),X'5032502f315f32',7,zeroblob(32),'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa','run','epoch',0,NULL,NULL,'time');").unwrap();let before:(i64,i64,i64)=conn.query_row("SELECT id,target_id,target_index FROM app_voice_im_read_status_actions",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap();n::im_inbox::initialize_schema(&conn).unwrap();let after:(i64,i64,i64)=conn.query_row("SELECT id,target_id,target_index FROM app_voice_im_read_status_actions",[],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?))).unwrap();assert_eq!(before,after);let hash:Option<Vec<u8>>=conn.query_row("SELECT recipient_hash FROM app_voice_im_read_status_actions",[],|r|r.get(0)).unwrap();assert!(hash.is_none());assert!(conn.execute("UPDATE app_voice_im_read_status_actions SET recipient_hash=X'01'",[]).is_err());n::im_inbox::initialize_schema(&conn).unwrap();}
